<?php
$isProjects=$view==='projects';
$layout=($_GET['layout']??'cards')==='list'?'list':'cards';
$pageUrl=$view==='overview'?'./':'./'.$view;
$status=is_string($_GET['status']??null)?$_GET['status']:'';
if(!in_array($status,['Upcoming','Under construction','Completed'],true))$status='';
$items=$filtered;
if($isProjects){
 require_once dirname(__DIR__).'/Config/projects-store.php';
 $items=[];
 foreach(projectData(currentUser()['role']==='admin') as $project){
  if(($query===''||mb_stripos($project['title'].' '.$project['city'],$query)!==false)&&($status===''||$project['development_status']===$status)){
   $project['status']=$project['development_status'];$items[]=$project;
  }
 }
}
$totalItems=count($items);$perPage=6;$totalPages=max(1,(int)ceil($totalItems/$perPage));
$page=min($totalPages,max(1,(int)(is_scalar($_GET['page']??null)?$_GET['page']:1)));$offset=($page-1)*$perPage;$items=array_slice($items,$offset,$perPage);
$pageParams=['layout'=>$layout,'q'=>$query];$pageParams[$isProjects?'status':'purpose']=$isProjects?$status:$purpose;
$paginationUrl=static fn($number)=>$pageUrl.'?'.http_build_query(array_merge($pageParams,['page'=>$number]));
function adminItemUrl(array $item,bool $project): string {return $project?'../project.php?slug='.rawurlencode($item['slug']):'../property.php?slug='.rawurlencode($item['slug']);}
?>
<section class="panel inventory"><div class="panel-title"><div><h2><?= $isProjects?'Project inventory':'Property inventory' ?></h2><p><?= $totalItems ?> <?= $isProjects?'projects':'properties' ?> found</p></div><div class="layout-switch" aria-label="Display layout"><?php foreach(['cards'=>'Cards','list'=>'List'] as $value=>$label): $params=['layout'=>$value,'q'=>$query];if($isProjects)$params['status']=$status;else $params['purpose']=$purpose; ?><a href="<?= e($pageUrl.'?'.http_build_query($params)) ?>" <?= $layout===$value?'aria-current="true"':'' ?>><?= listingIcon($value==='cards'?'grid':'filter') ?><?= e($label) ?></a><?php endforeach; ?></div></div>
<form class="table-toolbar" method="get" action="<?= e($pageUrl) ?>"><input type="hidden" name="layout" value="<?= e($layout) ?>"><label class="search-field"><?= listingIcon('search') ?><span class="sr-only">Search <?= $isProjects?'projects':'properties' ?></span><input name="q" type="search" value="<?= e($query) ?>" placeholder="Search name or location..."></label><label><span class="sr-only"><?= $isProjects?'Project status':'Listing purpose' ?></span><select name="<?= $isProjects?'status':'purpose' ?>"><option value="">All <?= $isProjects?'statuses':'listings' ?></option><?php foreach($isProjects?['Upcoming','Under construction','Completed']:['Rent','Sell'] as $option): ?><option <?= ($isProjects?$status:$purpose)===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="primary-button" type="submit">Filter</button><?php if($query!==''||($isProjects?$status:$purpose)!==''): ?><a class="text-link" href="<?= e($pageUrl.'?layout='.$layout) ?>">Reset</a><?php endif; ?></form>
<?php if(!$items): ?><div class="empty-state">No <?= $isProjects?'projects':'properties' ?> match your filters. Try another search or reset filters.</div>
<?php elseif($layout==='cards'): ?><div class="admin-inventory-grid"><?php foreach($items as $item): ?><article class="inventory-card"><a href="<?= e(adminItemUrl($item,$isProjects)) ?>" aria-label="View <?= e($item['title']) ?>"><img src="../<?= e(substr($item['image'],2)) ?>" alt="Illustrative image for <?= e($item['title']) ?>" width="512" height="340" loading="lazy"></a><div><div class="inventory-card-badges"><?php if(!$isProjects): ?><span class="property-publication <?= ($item['status']??'published')==='published'?'is-published':'' ?>"><?= ($item['status']??'published')==='published'?'Published':'Unpublished' ?></span><?php endif; ?><span class="subtle-tag"><?= e($isProjects?$item['status']:$item['purpose']) ?></span></div><h3><a href="<?= e(adminItemUrl($item,$isProjects)) ?>"><?= e($item['title']) ?></a></h3><p><?= e($item['city']) ?> &middot; <?= e($item['type']) ?></p><?php if($isProjects): ?><label class="inventory-progress">Sample progress <strong><?= $item['progress'] ?>%</strong><progress max="100" value="<?= $item['progress'] ?>"><?= $item['progress'] ?>%</progress></label><?php else: ?><p><?= $item['beds'] ?> beds &middot; <?= number_format($item['area']) ?> sq.ft</p><strong class="inventory-price"><?= e(listingPrice($item)) ?><?= $item['purpose']==='Rent'?' / month':'' ?></strong><?php endif; ?><div class="inventory-card-actions"><?php if(!$isProjects&&currentUser()['role']==='admin'): ?><a class="property-edit-link" href="./create-property?slug=<?= rawurlencode($item['slug']) ?>" aria-label="Edit <?= e($item['title']) ?>"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg>Edit</a><?php endif; ?><?php if(!$isProjects): ?><?php if(currentUser()['role']==='admin'): ?><form method="post" action="./properties" class="property-publication-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="slug" value="<?= e($item['slug']) ?>"><input type="hidden" name="status" value="<?= ($item['status']??'published')==='published'?'unpublished':'published' ?>"><button type="submit" class="property-entry-button"><?= ($item['status']??'published')==='published'?'Unpublish':'Publish' ?></button></form><?php endif; ?><?php endif; ?><a class="inventory-view" href="<?= e(adminItemUrl($item,$isProjects)) ?>">View &nearr;</a></div></div></article><?php endforeach; ?></div>
<?php else: ?><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $isProjects?'Projects':'Properties' ?> list"><table class="mobile-card-table"><thead><tr><th><?= $isProjects?'Project':'Property' ?></th><th>Location</th><th>Type</th><th><?= $isProjects?'Status':'Purpose' ?></th><th><?= $isProjects?'Sample progress':'Price' ?></th><th><span class="sr-only">Details</span></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td class="mobile-card-heading"><div class="property-cell"><img src="../<?= e(substr($item['image'],2)) ?>" alt="" width="58" height="48" loading="lazy"><div><strong><?= e($item['title']) ?></strong><span>Sample <?= $isProjects?'project concept':($item['beds'].' beds · '.number_format($item['area']).' sq.ft') ?></span></div></div></td><td data-label="Location"><?= e($item['city']) ?></td><td data-label="Type"><?= e($item['type']) ?></td><td data-label="<?= $isProjects?'Status':'Purpose' ?>"><span class="subtle-tag"><?= e($isProjects?$item['status']:$item['purpose']) ?></span></td><td class="price-cell" data-label="<?= $isProjects?'Progress':'Price' ?>"><?php if($isProjects): ?><?= $item['progress'] ?>%<progress class="table-progress" max="100" value="<?= $item['progress'] ?>"><?= $item['progress'] ?>%</progress><?php else: ?><?= e(listingPrice($item)) ?><?= $item['purpose']==='Rent'?'<small>/ month</small>':'' ?><?php endif; ?></td><td data-label="Details"><?php if(!$isProjects): ?><span class="property-publication <?= ($item['status']??'published')==='published'?'is-published':'' ?>"><?= ($item['status']??'published')==='published'?'Published':'Unpublished' ?></span><?php if(currentUser()['role']==='admin'): ?><form method="post" action="./properties" class="property-publication-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="slug" value="<?= e($item['slug']) ?>"><input type="hidden" name="status" value="<?= ($item['status']??'published')==='published'?'unpublished':'published' ?>"><button type="submit" class="property-entry-button"><?= ($item['status']??'published')==='published'?'Unpublish':'Publish' ?></button></form><?php endif; ?><?php endif; ?><?php if(!$isProjects&&currentUser()['role']==='admin'): ?><a class="property-edit-link" href="./create-property?slug=<?= rawurlencode($item['slug']) ?>" aria-label="Edit <?= e($item['title']) ?>"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg>Edit</a><?php endif; ?><a class="detail-link" href="<?= e(adminItemUrl($item,$isProjects)) ?>" aria-label="View <?= e($item['title']) ?>">&nearr;</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($totalItems): ?><div class="inventory-pagination"><p>Showing <?= $offset+1 ?>&ndash;<?= $offset+count($items) ?> of <?= $totalItems ?></p><?php if($totalPages>1): ?><nav aria-label="Inventory pages"><?php if($page>1): ?><a href="<?= e($paginationUrl($page-1)) ?>" rel="prev" aria-label="Previous page">&lsaquo; Previous</a><?php else: ?><span aria-disabled="true">&lsaquo; Previous</span><?php endif; ?><?php $last=0;foreach(array_unique([1,max(1,$page-1),$page,min($totalPages,$page+1),$totalPages]) as $number): if($number>$last+1): ?><span class="pagination-gap">&hellip;</span><?php endif; ?><a href="<?= e($paginationUrl($number)) ?>" <?= $number===$page?'aria-current="page"':'' ?> aria-label="Page <?= $number ?>"><?= $number ?></a><?php $last=$number;endforeach; ?><?php if($page<$totalPages): ?><a href="<?= e($paginationUrl($page+1)) ?>" rel="next" aria-label="Next page">Next &rsaquo;</a><?php else: ?><span aria-disabled="true">Next &rsaquo;</span><?php endif; ?></nav><?php endif; ?></div><?php endif; ?>
<p class="inventory-note">Sample content only. <?= $isProjects?'Progress is illustrative; these are not live project announcements.':'Listings are not verified live offers.' ?></p></section>
